registry={'schema':1,'scope':'GUI519-derived warlock-preview-provider-v1 full selected closure','sourceModuleCount':len(modules),'components':components,'modules':modules,'assets':assets,'renderedClasses':sorted(classes),'coverage':{'allStaticClassesAssigned':True,'selectedClosureOnly':True},'integrationGaps':['Other archived/native/input lanes are not integrated into this selected closure.','No product renderer or native behavior is changed by catalog code.'],'nativeAcceptance':False,'fullReleaseAccepted':False}
