pairs=[{'foreground':f,'background':b,'minimum':4.5,'purpose':'text'} for f in ['text','muted','accent','positive','warning','danger'] for b in ['background','surface']]+[{'foreground':f,'background':b,'minimum':3,'purpose':'boundary/focus'} for f in ['border','accent'] for b in ['background','surface']]
tokens={'schema':1,'brandReferenceSHA256':sha(REPO/'docs/warlock-brand/v1/tokens.json'),'reference':themes,'semantic':semantic,'component':component,'pairs':pairs,'geometry':{'minimumCatalogTargetPx':32,'controlRadiusPx':6,'specimenRadiusPx':12,'readerMeasureCh':70},'motion':{'demonstrations':'explicit actions; no timer','reducedMotion':'no recurring or automatic motion','nativeTiming':'unchanged; catalog values do not define product deadlines'}}
